const todos = $input.all().map((i) => i.json);
// Só quem trabalhou no dia: teve venda, lançou falta ou fez contato —
// sem nenhum desses três, o vendedor some da mensagem (não é
// "zerado", é "sem atividade registrada hoje").
const itens = todos.filter((v) => v.qtd_notas_dia > 0 || v.lancou_falta || v.fez_contato);
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// Uma medalha só por vendedor: a posição do dia (ranking por margem_dia,
// já que a lista vem ordenada assim). A faixa de comissão da semana
// continua aparecendo, só que em texto ("faixa X%"), sem emoji próprio --
// duas medalhas na mesma linha (posição + faixa) tava poluído.
const MEDALHA_POSICAO = ['🥇', '🥈', '🥉'];

function fmtBRL(v) {
  return (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

function marca(v) {
  return v ? '✅' : '❌';
}

const linhas = [`📊 *Performance do dia — ${hojeLabel}*`, ''];

if (itens.length === 0) {
  linhas.push('Ninguém registrou atividade hoje.');
} else {
  itens.forEach((v, idx) => {
    const posicao = MEDALHA_POSICAO[idx] ?? '▪️';
    const faixa = v.faixa_semana != null ? Number(v.faixa_semana) : 3;
    linhas.push(`${posicao} *${v.nome_vendedor}*`);
    linhas.push(`💰 Hoje: ${fmtBRL(v.margem_dia)} (${v.percentual_dia ?? 0}% da meta do dia)`);
    linhas.push(`📅 Semana: ${fmtBRL(v.margem_semana)} (${v.percentual_semana ?? 0}% da meta): *faixa ${faixa}%*`);
    linhas.push(`🧾 ${v.qtd_notas_dia} vendas: ${v.vendas_cliente_real} com cliente, ${v.vendas_proprio_cpf} no CPF do vendedor, ${v.vendas_sem_cliente} sem cliente`);
    linhas.push(`📦 Lançou falta: ${marca(v.lancou_falta)}`);
    linhas.push(`📞 Fez contato: ${marca(v.fez_contato)}`);
    // separador + linha em branco dupla -- mais respiro entre um vendedor e outro
    linhas.push('┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄');
    linhas.push('');
    linhas.push('');
  });
  // tira o respiro extra do final (depois do último vendedor não precisa)
  while (linhas.length > 0 && linhas[linhas.length - 1] === '') linhas.pop();
}

return [{ json: { mensagem: linhas.join('\n').trim() } }];

// Só chega aqui quem ficou 2 dias seguidos (hoje E ontem) com margem
// abaixo da meta do dia — não distingue "folga/dia livre" de
// "desempenho fraco" (não checa atividade, diferente da mensagem de
// recap) — é uma primeira versão, calibrar depois se der falso positivo.
const linhas = $input.all().map((i) => i.json);
if (linhas.length === 0) {
  return [];
}
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

function fmtBRL(v) {
  return (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

const blocos = linhas.map(
  (v) =>
    `⚠️ *${v.nome_vendedor}*\nHoje: ${fmtBRL(v.margem_hoje)} · Ontem: ${fmtBRL(v.margem_ontem)} (meta do dia: ${fmtBRL(v.meta_dia)})`
);

const mensagem = `📉 *2 dias seguidos abaixo da meta — ${hojeLabel}*\n\n${blocos.join('\n\n')}`;

return [{ json: { mensagem } }];
